<?php
$conn = mysqli_connect("localhost", "root", "", "BD123456");

$theme = $_POST["theme"];

$r1 = mysqli_query($conn, "SELECT * FROM Sondage WHERE Theme='$theme'");
$s = mysqli_fetch_array($r1);

$numS = $s["NumS"];
$dateDebut = $s["DateDebut"];

if ($dateDebut > date("Y-m-d")) {
    echo "Sondage non encore lancé !";
} else {
    $r2 = mysqli_query($conn, "SELECT COUNT(DISTINCT IdParticipant) AS Total FROM Reponse WHERE NumS=$numS");
    $t = mysqli_fetch_array($r2);
    $total = $t["Total"];

    if ($total == 0) {
        echo "Aucune participation enregistrée à ce moment";
    } else {
        $rF = mysqli_query($conn, "SELECT COUNT(DISTINCT R.IdParticipant) AS TotalF
                                   FROM Reponse R, Participant P
                                   WHERE R.IdParticipant=P.IdParticipant
                                   AND R.NumS=$numS AND P.Genre='F'");
        $f = mysqli_fetch_array($rF);
        $totalF = $f["TotalF"];

        $rM = mysqli_query($conn, "SELECT COUNT(DISTINCT R.IdParticipant) AS TotalM
                                   FROM Reponse R, Participant P
                                   WHERE R.IdParticipant=P.IdParticipant
                                   AND R.NumS=$numS AND P.Genre='M'");
        $m = mysqli_fetch_array($rM);
