        echo "</tr>";

        $rq = mysqli_query($conn, "SELECT * FROM Question WHERE NumS=$numS");

        while ($q = mysqli_fetch_array($rq)) {
            $numQ = $q["NumQ"];
            $contenu = $q["Contenu"];

            $rO = mysqli_query($conn, "SELECT COUNT(*) AS nb FROM Reponse WHERE NumS=$numS AND NumQ=$numQ AND Rep='O'");
            $o = mysqli_fetch_array($rO);
            $nbO = $o["nb"];

            $rN = mysqli_query($conn, "SELECT COUNT(*) AS nb FROM Reponse WHERE NumS=$numS AND NumQ=$numQ AND Rep='N'");
            $n = mysqli_fetch_array($rN);
            $nbN = $n["nb"];

            $rS = mysqli_query($conn, "SELECT COUNT(*) AS nb FROM Reponse WHERE NumS=$numS AND NumQ=$numQ AND Rep='S'");
            $sa = mysqli_fetch_array($rS);
            $nbS = $sa["nb"];

            $pO = round(($nbO * 100) / $total, 2);
            $pN = round(($nbN * 100) / $total, 2);
            $pS = round(($nbS * 100) / $total, 2);

            echo "<tr>";
            echo "<td>".$numQ."</td>";
            echo "<td>".$contenu."</td>";
            echo "<td>".$pO."%</td>";
            echo "<td>".$pN."%</td>";
            echo "<td>".$pS."%</td>";
            echo "</tr>";
        }

        echo "</table>";
    }
}

mysqli_close($conn);
?>

