        valide=5<=N<=20

## module qui rempli le  tableau par des nombres aléatoires 
def generer_tab(T,N):
    for i in range(N):
        T[i]=randint(-99,99)

def tri_bulles (T,N):
    sortie=False
    while sortie==False:
        permut=False
        for i in range(N-1):
            if T[i+1]<T[i]:
                aux=T[i+1]
                T[i+1]=T[i]
                T[i]=aux
                permut=True
        sortie=(permut==False)

def affiche(T,N):
    for i in range (N):
        print(T[i],end=' | ')
    print()

