import numpy as np
from random import randint
def saisie_taille():
    arret=False
    while not arret:
        try:
            n=int(input("Entrer la taille de T(5-10):"))
            arret=5<=n<=10
        except:
            arret=False
            
    return n
def remplir(t,n):
    ## remplissage manuel
    for i in range(n):
        arret=False
        while not arret:
            try:
                t[i]=int(input("T["+str(i)+"]="))
                arret=True
            except:
                arret=False
            

def afficher(t,n):
    for i in range(n):
        print(t[i]," | ",end="")
    print()
def tri_comptage(t,n):
    # initialise le tableau par des 0
    rang=np.array([int()]*n) 
    tmp=np.array([int]*n)
    for i in range(n-1):
        for j in range(i+1,n):
            if t[i]<t[j]:
                rang[j]=rang[j]+1
            else:
                rang[i]=rang[i]+1
    ## placer les elements de t dans tmp
    for i in range(n):
        tmp[rang[i] ]=t[i]
    ## recopie de tmp dans t
    for i in range(n):
        t[i]=tmp[i]
                
        
########### PP ########
n=saisie_taille()
t=np.array([int]*n)
remplir(t,n)
afficher(t,n)
tri_comptage(t,n)
print("----- après Tri comptage ----")
afficher(t,n)

