from random import randint
def saisie():
    global N
    valide=False
    while valide==False:
        N=int(input("Entrer le nombre d'éléments :"))
        valide=5<=N<=20
def generer_tab(T,N):
    for i in range(N):
        T[i]=randint(-99,99)
def tri_insertion (T,N):
     for i in range(1,N):
        aux=T[i]
        p=i-1
        while (p>=0) and (T[p]>aux):
            T[p+1]=T[p]
            p=p-1
        T[p+1]=aux

def affiche(T,N):
    for i in range (N):
        print(T[i],end=' | ')
    print()

############ Programme Principale ##########
print('------------ Tri par insertion -----------')
saisie()
T=[0]*N
generer_tab(T,N)
print("*** Avant le tri***" )
affiche(T,N)
tri_insertion(T,N)
print("*** Après le tri***" )
affiche(T,N)





